function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // face
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50 + 20 * Math.sin(t), 0, 2 * Math.PI);
  ctx.fill();

  // eyes
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 - 20 + 10 * Math.sin(t), H/2 - 20 + 10 * Math.cos(t), 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 + 20 + 10 * Math.cos(t), H/2 - 20 - 10 * Math.sin(t), 10, 0, 2 * Math.PI);
  ctx.fill();

  // body
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50 + 20 * Math.sin(t));
  ctx.lineTo(W/2, H - 50 - 20 * Math.cos(t));
  ctx.stroke();

  // arms
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 70 + 20 * Math.sin(t));
  ctx.lineTo(W/2 - 50 + 20 * Math.cos(t), H/2 + 100 + 20 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 70 + 20 * Math.sin(t));
  ctx.lineTo(W/2 + 50 - 20 * Math.cos(t), H/2 + 100 - 20 * Math.sin(t));
  ctx.stroke();

  // legs
  ctx.beginPath();
  ctx.moveTo(W/2, H - 50 - 20 * Math.cos(t));
  ctx.lineTo(W/2 - 30 + 15 * Math.cos(t), H - 20 - 15 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H - 50 - 20 * Math.cos(t));
  ctx.lineTo(W/2 + 30 - 15 * Math.cos(t), H - 20 + 15 * Math.sin(t));
  ctx.stroke();

  ctx.restore();
}
